import re

from taf.ul.bts_components import Smod, Bbmod
from taf.transport.ssh import ssh

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result
from taf.rfrl.procedures.resources.python.bbmod_operations.exceptions import CommandExecutionError, PIDNotFound, \
    TopologyNotFound, CPUIdError, SmodIpNotReachable
from taf.rfrl.procedures.resources.python.connections import get_ssh_connection_credentials, wait_for_site
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_bbmod_serial_number, \
    get_smod_active_role_for_connected_bbmod


class BbmodOperations:
    """
    Responsible for operations executed on BBMODs via SMOD ssh session.
    """

    def __init__(self):
        self._bts_type = None
        self._bbmods_attributes_master = None
        self._bbmods_attributes_slave = None
        self._bbmods_credentials = {}

    @property
    def bts_type(self):
        if self._bts_type is None:
            self._bts_type = TestLine().get_type_of_setup()
        return self._bts_type

    @property
    def bbmod_attributes_master(self):
        if self._bbmods_attributes_master is None:
            self._bbmods_attributes_master = self._get_bbmods_topology_info(slave_bts=False)
        return self._bbmods_attributes_master

    @property
    def bbmod_attributes_slave(self):
        if self._bbmods_attributes_slave is None:
            self._bbmods_attributes_slave = self._get_bbmods_topology_info(slave_bts=True)
        return self._bbmods_attributes_slave

    @log_input_and_output
    def execute_ssh_command(self, bbmod_id, command, connection, bbmod_cpu=0, timeout=10):
        """
        Executes command on BBMOD

        :param bbmod_id: BBMOD configuration ID of baseband module to connect
        :type bbmod_id: int or str
        :param command: command to be executed on BBMOD via ssh
        :type command: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param bbmod_cpu: ID of other BBMOD cpu (for lfc, loki or thor cpu). Defaults to 0 means that operation will
                          be executed on main bbmod's cpu (lfs).
        :type bbmod_cpu: int or str
        :param timeout: timeout (in seconds) for send command operation on BBMOD, defaults to 10.
        :type timeout: int

        :return: command output
        :rtype: str
        """
        return self._execute_ssh_command(bbmod_id=bbmod_id, bbmod_cpu=bbmod_cpu, command=command, connection=connection,
                                         timeout=timeout)

    @log_input_and_output
    def kill_bbmod_process_by_name(self, bbmod_id, process_name, connection, bbmod_cpu=0, timeout=10):
        """
        Kills process on bbmod by given process name and returns PID of killed process.

        :param bbmod_id: BBMOD configuration ID of baseband module to connect
        :type bbmod_id: int
        :param process_name: full name or pattern to bbmod's process to kill, e.g.: '/usr/bin/l1_application_rt'
        :type process_name: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param bbmod_cpu: ID of other BBMOD cpu (for lfc, loki or thor cpu). Defaults to 0 means that operation will
                          be executed on main bbmod's cpu (lfs).
        :type bbmod_cpu: int or str
        :param timeout: timeout (in seconds) for send kill process command on BBMOD, defaults to 10.
        :type timeout: int

        :return: PID of killed process
        :rtype: int

        :raises PIDNotFound exception when no process ID was found with the given process name
        :raises CommandExecutionError exception when 'kill -11' command was not executed successfully.
        """
        bbmod_credentials = self._get_bbmod_ssh_credentials(bbmod_id=bbmod_id, connection=connection)
        processes_print_command = f"ps aux | grep {process_name}"

        try:
            smod, smod_alias = self._create_smod_connection(slave_bts=bbmod_credentials['slave_bts'])
            bbmod = self._create_bbmod_connection(bbmod_credentials, smod_alias, bbmod_cpu=bbmod_cpu)

            pid_list = self._get_list_of_process_ids(processes_print_command=processes_print_command,
                                                     bbmod_connection=bbmod, timeout=timeout)
            if not pid_list:
                raise PIDNotFound(f"PID not found for given process name:'{process_name}'")

            kill_result = bbmod.execute(command=f"kill -11 {pid_list[0]}", timeout=timeout)

            if "No such process" in kill_result or "unknown" in kill_result:
                raise CommandExecutionError(f"Kill process failure: '{kill_result}'")

        finally:
            bbmod.close_connection()
            smod.close_connection()

        return int(pid_list[0])

    @log_input_and_output
    def _get_bbmods_attributes(self, slave_bts):
        """
        Gets attributes of all baseband modules connected to master or slave bts module.

        :param slave_bts: True if connection should be performed to slave bts with fullrack configuration,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool

        :return: attributes of all baseband modules connected to master or slave bts modul,
                 e.g. : [{'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP', 'slot': 'slave B2',
                          'hw_name': 'ABIP', 'address': 'fsp2s0icom', 'login_shortcut': 'bsh 2:0',
                          'other_cpus': {'1': {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu',
                                               'alias': 'B2_ABIP', 'slot': 'slave B2', 'hw_name': 'ABIP',
                                               'address': 'fsp2s1icom', 'login_shortcut': 'bsh 2:1'}},
                          'serial_number': 'L1232004079', 'slave_bts': False},
                         {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B3_ABIP',
                          'slot': 'slave B3', 'hw_name': 'ABIP', 'address': 'fsp3s0icom', 'login_shortcut': 'bsh 3:0',
                          'other_cpus': {'1': {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu',
                                               'alias': 'B3_ABIP', 'slot': 'slave B3', 'hw_name': 'ABIP',
                                               'address': 'fsp3s1icom', 'login_shortcut': 'bsh 3:1'}},
                          'serial_number': 'L1232004082', 'slave_bts': False}]
        :rtype: list of dict
        """
        if slave_bts:
            return self.bbmod_attributes_slave
        return self.bbmod_attributes_master

    @log_input_and_output
    def _get_bbmod_ssh_credentials(self, bbmod_id, connection):
        """
        Gets BBMOD ssh credentials based on provided BBMOD ID. IP address is getting from smod FRIps.txt file,
        login and password are getting from init file, serial number is getting using admin api.

        :param bbmod_id: BBMOD configuration ID of particular baseband module, e.g.: 1
        :type bbmod_id: str or int
        :param connection: AdminConnection object or if used, string name alias
        :type connection: AdminConnection or str

        :return: dict of BBMOD credentials with following keys: 'ip', 'username', 'password' and 'sn',
                 e.g. : {'ip': '172.22.8.2', 'username': 'rfsw',
                         'password': 'KRG3dFggxxHw+s0z64U0AR22VyjfnXdHrAVdSv5jpc4=',
                         'sn': '1M222600258'}
        :rtype: dict

        :raises TopologyNotFound exception when bbmod topology info has not found for BBMOD id.
        """
        if not self._bbmods_credentials.get(str(bbmod_id)):
            bbmod_topology_info = self._get_bbmod_topology_info_by_id(bbmod_id=bbmod_id, connection=connection)
            self._bbmods_credentials[str(bbmod_id)] = bbmod_topology_info

        return self._bbmods_credentials[str(bbmod_id)]

    @log_input_and_output
    def _get_bbmod_topology_info_by_id(self, bbmod_id, connection):
        """
        Gets topology info of particular baseband module.

        :param bbmod_id: BBMOD configuration ID of particular baseband module, e.g.: 1
        :type bbmod_id: str or int
        :param connection: AdminConnection object or if used, string name alias
        :type connection: AdminConnection or str

        :return: dictionary with topology info of particular baseband module, e.g.:
                 {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP',
                  'slot': 'slave B2', 'hw_name': 'ABIP', 'address': 'fsp2s0icom', 'login_shortcut': 'bsh 2:0',
                  'other_cpus': {'1': {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP',
                                       'slot': 'slave B2', 'hw_name': 'ABIP', 'address': 'fsp2s1icom',
                                       'login_shortcut': 'bsh 2:1'}},
                  'serial_number': 'L1232004079', 'slave_bts': False}
        :rtype: dict

        :raises TopologyNotFound exception when bbmod topology info has not found for BBMOD id.
        """
        bbmod_serial_number = get_bbmod_serial_number(bbmod_id=bbmod_id, connection=connection)
        smod_active_role = get_smod_active_role_for_connected_bbmod(bbmod_id=bbmod_id, connection=connection)
        is_bbmod_connected_to_slave_bts = True if smod_active_role == "Secondary" else False

        for bbmod_attributes in self._get_bbmods_attributes(slave_bts=is_bbmod_connected_to_slave_bts):
            if bbmod_attributes['serial_number'] == bbmod_serial_number:
                return bbmod_attributes

        raise TopologyNotFound(f"Topology info has not found for BBMOD-{bbmod_id} (S/N: {bbmod_serial_number})")

    @log_input_and_output
    def _get_bbmods_topology_info(self, slave_bts=False):
        """
        Gets bbmods topology info included serial number.

        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool

        :return: list of dictionaries with bbmods info, e.g.:
                 [{'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP', 'slot': 'slave B2',
                   'hw_name': 'ABIP', 'address': 'fsp2s0icom', 'login_shortcut': 'bsh 2:0',
                   'serial_number': 'L1205102683', 'slave_bts' : False}]
        :rtype: list of dict
        """
        smod, smod_alias = self._create_smod_connection(slave_bts=slave_bts)
        bbmods_attributes = smod.get_bbmods_topology_info(get_other_cpus_info=True, slave_bts=slave_bts)
        log_result(f"Bbmods topology info: {bbmods_attributes}")

        bbmods_attributes_formated = self._format_bbmods_attributes_with_all_cpus(bbmods_attributes)

        bbmods_topology_info = []
        for bbmod_attributes in bbmods_attributes_formated:
            bbmod = self._create_bbmod_connection(bbmod_attributes, smod_alias)
            bbmod_attributes['serial_number'] = bbmod.get_bbmod_serial_number()
            bbmod_attributes['slave_bts'] = slave_bts
            bbmods_topology_info.append(bbmod_attributes)
            bbmod.close_connection()

        smod.close_connection()

        return bbmods_topology_info

    @staticmethod
    @log_input_and_output
    def _format_bbmods_attributes_with_all_cpus(bbmods_attributes):
        """
        Formats baseband attributes info. Places the attributes of other processors into the attributes of the main fct
        processor. Attributes of other cpus will be available in main cpu attributes under 'other_cpus' key with
        specified processor id, e.g.: 'other_cpus': {'1': {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu',
        'alias': 'B2_ABIP', 'slot': 'slave B2', 'hw_name': 'ABIP', 'address': 'fsp2s1icom', 'login_shortcut':
        'bsh 2:1'}}

        :param bbmods_attributes: attributes of all bbmod's processors.
        :type bbmods_attributes: list of dict

        :return: dictionary with topology info of particular baseband module, e.g.:
                 [{'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP',
                   'slot': 'slave B2', 'hw_name': 'ABIP', 'address': 'fsp2s0icom', 'login_shortcut': 'bsh 2:0',
                   'other_cpus': {'1': {'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP',
                                        'slot': 'slave B2', 'hw_name': 'ABIP', 'address': 'fsp2s1icom',
                                        'login_shortcut': 'bsh 2:1'}},
                   'serial_number': 'L1232004079', 'slave_bts': False}]
        :rtype: dict

        """
        main_cpus_attributes = []
        other_cpus_attributes = []
        for bbmod_attributes in bbmods_attributes:
            if ":0" in bbmod_attributes['login_shortcut']:
                main_cpus_attributes.append(bbmod_attributes)
            else:
                other_cpus_attributes.append(bbmod_attributes)

        formated_bbmod_attributes = []
        for main_cpu in main_cpus_attributes:
            main_cpu["other_cpus"] = {}

            for other_cpu in other_cpus_attributes:
                if other_cpu['slot'] == main_cpu['slot']:
                    other_bbmod_cpu_index = other_cpu['login_shortcut'][-1]
                    main_cpu["other_cpus"][other_bbmod_cpu_index] = other_cpu

            formated_bbmod_attributes.append(main_cpu)

        return formated_bbmod_attributes

    @log_input_and_output
    def _create_smod_connection(self, slave_bts=False):
        """
        Creates ssh connection to smod module.

        :param slave_bts: True if connection should be performed to slave bts with fullrack configuration,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool

        :return: smod constructor and session alias (master_bts or slave_bts or slave_bts_vm)
        :rtype: tuple
        """
        smod = Smod()

        if slave_bts:
            credentials = get_ssh_connection_credentials(bts_type=self.bts_type, common_unit_id=1)
            alias = 'slave_bts'
        else:
            credentials = get_ssh_connection_credentials(bts_type=self.bts_type)
            alias = 'master_bts'
        proxy = None

        if slave_bts:
            proxy = 'slave_bts_vm'
            vm_credentials = TestLine().get_bts_test_pc_credentials(bts_type=self.bts_type, slave=slave_bts)
            credentials['host'] = self._get_slave_smod_ip(slave_get_ssh_connection_credentials=credentials,
                                                          slave_bts_test_pc_credentials=vm_credentials)
            ssh().connect_to(hostname=vm_credentials['host'], username=vm_credentials['user'],
                             password=vm_credentials['password'], alias=proxy)

        smod.connect_to(address=credentials['host'], username=credentials['username'], password=credentials['password'],
                        proxy=proxy, alias=alias)

        return smod, alias

    @log_input_and_output
    def _get_slave_smod_ip(self, slave_get_ssh_connection_credentials, slave_bts_test_pc_credentials, timeout=60):
        is_reachable, reachable_slave_ip = wait_for_site(ip=slave_get_ssh_connection_credentials['host'],
                                                         bts_type=self.bts_type,
                                                         slave=True,
                                                         timeout=timeout,
                                                         ssh_credentials=slave_bts_test_pc_credentials)
        if is_reachable:
            log_result(f"Slave SMOD IP: '{reachable_slave_ip}'")
            return reachable_slave_ip
        else:
            raise SmodIpNotReachable("Slave SMOD IP is not reachable")

    @staticmethod
    @log_input_and_output
    def _create_bbmod_connection(bbmod_attributes, proxy, bbmod_cpu=0):
        """
        Creates ssh connection to bbmod module.
        :param bbmod_attributes: attributes info of particular bbmod
        :type bbmod_attributes: dict
        :param proxy: alias of ssh connection session to smod to which bbmod is connected
        :type proxy: str
        :param bbmod_cpu: id pf bbmod processor, defaults to zero means connection to main fct cpu will be created.
        :type bbmod_cpu: int

        :return: bbmod constructor
        :rtype: class obj
        """
        if int(bbmod_cpu) == 0:
            bbmod_address = bbmod_attributes['address']
            bbmod_alias = bbmod_attributes['alias']

        else:
            if bbmod_attributes['other_cpus'].get(str(bbmod_cpu)):
                bbmod_address = bbmod_attributes['other_cpus'][str(bbmod_cpu)]['address']
                bbmod_alias = f"{bbmod_attributes['alias']}_{bbmod_cpu}"
            else:
                raise CPUIdError(f"Other CPU with ID: '{bbmod_cpu}' does not exist in bbmod attributes: "
                                 f"{bbmod_attributes}")

        bbmod = Bbmod()
        bbmod.connect_to(address=bbmod_address, username=bbmod_attributes['username'],
                         password=bbmod_attributes['password'], proxy=proxy, alias=bbmod_alias)

        return bbmod

    @log_input_and_output
    def _execute_ssh_command(self, bbmod_id, command, connection, bbmod_cpu=0, timeout=10):
        """
        Executes command on BBMOD using ssh connection (via SMOD ssh connection). SMOD and BBMOD ssh sessions are
        terminated at the end.

        :param bbmod_id: BBMOD configuration ID of baseband module to connect
        :type bbmod_id: int or str
        :param command: command to be executed on BBMOD via ssh
        :type command: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param bbmod_cpu: ID of other BBMOD cpu (for lfc, loki or thor cpu). Defaults to 0 means that operation will
                          be executed on main bbmod's cpu (lfs).
        :type bbmod_cpu: int or str
        :param timeout: timeout (in seconds) for send command operation on BBMOD, defaults to 10.
        :type timeout: int

        :return: command output
        :rtype: str
        """
        bbmod_credentials = self._get_bbmod_ssh_credentials(bbmod_id=bbmod_id, connection=connection)

        try:
            smod, smod_alias = self._create_smod_connection(slave_bts=bbmod_credentials['slave_bts'])
            bbmod = self._create_bbmod_connection(bbmod_credentials, smod_alias, bbmod_cpu=bbmod_cpu)

            command_output = bbmod.execute(command=command, timeout=timeout)
        finally:
            Bbmod().close_connection()
            Smod().close_connection()

        return command_output

    @log_input_and_output
    def _get_list_of_process_ids(self, processes_print_command, bbmod_connection, timeout):
        """
        Gets list of process IDs based on given print process command.
        :param processes_print_command: process print command, e.g.: 'ps aux | grep /usr/bin/l1_application_rt'
        :type processes_print_command: str
        :param bbmod_connection: Bbmod class instance with ssh connection established.
        :type bbmod_connection: class obj
        :param timeout: timeout (in seconds) for print command execution on bbmod module.
        :type timeout: int

        :return: list of process IDs based on given process print command, e.g.: ['1818', '7182', '7186']
        :rtype: list of str
        """
        ps_return = bbmod_connection.execute(command=processes_print_command, timeout=timeout)

        pid_list = []
        for line in ps_return.split("\n"):
            pid_search = re.match(r"root\s+[0-9]+\s.*", line)
            if not pid_search:
                pid_search = re.match(r"[0-9]+\s+root\s.*", line)

            if pid_search:
                pid = re.search(r"[0-9]+", pid_search.group())
                pid_list.append(pid.group())

        return pid_list
